    <section class="page-heading"><div><span>NUEVA SOLICITUD</span><h1>Crear referencia</h1><p>Registre el origen, coordinación de traslado e información clínica del paciente.</p></div><div class="steps"><span v-for="item in steps" :key="item.id" :class="{active:step>=item.id}"><b>{{ item.id }}</b>{{ item.label }}</span></div></section>
