      <section v-show="step===2"><header><span><i class="ph ph-ambulance"></i></span><div><small>PASO 2</small><h2>Coordinación de la referencia</h2></div></header><div class="form-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Médico que refiere *</label><input v-model.trim="form.medico_refiere_nombre" class="form-control" required></div><div class="col-md-3"><label class="form-label">Teléfono</label><input v-model.trim="form.medico_refiere_telefono" class="form-control"></div><div class="col-md-3"><label class="form-label">Especialidad</label><input v-model.trim="form.medico_refiere_especialidad" class="form-control"></div><div class="col-md-6"><label class="form-label">Médico receptor</label><select v-model="form.medico_receptor_id" class="form-select"><option value="">Por asignar</option><option v-for="item in doctors" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div><div class="col-md-3"><label class="form-label">Prioridad *</label><select v-model="form.prioridad_id" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in catalogs.prioridades" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div><div class="col-md-3"><label class="form-label">Tipo *</label><select v-model="form.tipo_referencia_id" class="form-select" required><option value="" disabled>Seleccione</option><option v-for="item in catalogs.tipos" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div><div class="col-md-4"><label class="form-label">Transporte</label><select v-model="form.medio_transporte_id" class="form-select"><option value="">No definido</option><option v-for="item in catalogs.transportes" :key="id(item)" :value="id(item)">{{ name(item) }}</option></select></div><div class="col-md-4"><label class="form-label">Especialidad solicitada</label><input v-model.trim="form.especialidad_solicitada" class="form-control"></div><div class="col-md-4"><label class