<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{buscarPacienteExacto}from'@/services/hospitalizacion';import{consultarCatalogosReferencia,crearReferencia,listarDiagnosticos,listarEstablecimientos,listarMedicosReceptores,listarPagadores}from'@/services/referencias';const router=useRouter(),step=ref(1),saving=ref(false),error=ref(''),dni=ref(''),patient=ref(null),searchingPatient=ref(false),establishments=ref([]),payers=ref([]),doctors=ref([]),diagnoses=ref([]),catalogs=reactive({prioridades:[],tipos:[],transportes:[]});const form=reactive({paciente_id:'',establecimiento_origen_id:'',tercero_contratante_id:'',medico_refiere_nombre:'',medico_refiere_telefono:'',medico_refiere_especialidad:'',medico_receptor_id:'',prioridad_id:'',tipo_referencia_id:'',medio_transporte_id:'',especialidad_solicitada:'',fecha_traslado_programada:'',observaciones:'',acompanante_nombre:'',acompanante_parentesco:'',acompanante_telefono:''}),clinical=reactive({motivo_consulta:'',enfermedad_actual:'',antecedentes_relevantes:'',diagnostico_principal_cie10:'',alergias:'',examenes_realizados:'',tratamiento_actual:'',observaciones_clinicas:''});const array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],id=x=>x.id??x.paciente_id??x.id_paciente,name=x=>x.nombre??x.name??x.razon_social??x.descripcion,patientName=computed(()=>name(patient.value)||[patient.value?.primer_nombre,patient.value?.primer_apellido].filter(Boolean).join(' ')),initials=n=>String(n||'P').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase(),canContinue=computed(()=>step.value===1?form.paciente_id&&form.establecimiento_origen_id:step.value===2?form.medico_refiere_nombre&&form.prioridad_id&&form.tipo_referencia_id:clinical.motivo_consulta&&clinical.diagnostico_principal_cie10);async function findPatient(){searchingPatient.value=true;error.value='';try{const r=await buscarPacienteExacto(dni.value);patient.value=r?.data||r;form.paciente_id=id(patient.value)}catch(e){patient.value=null;form.paciente_id='';error.value=obtenerMensajeError(e)}finally{searchingPatient.value=false}}const pick=(s,keys)=>{for(const k of keys)if(Array.isArray(s?.[k]))return s[k];return[]};const clean=o=>Object.fromEntries(Object.entries(o).filter(([,v])=>v!==''&&v!==null&&v!==undefined));async function submit(){if(!canContinue.value)return;saving.value=true;error.value='';try{const payload={...clean(form),paciente_id:Number(form.paciente_id),establecimiento_origen_id:Number(form.establecimiento_origen_id),prioridad_id:Number(form.prioridad_id),tipo_referencia_id:Number(form.tipo_referencia_id),detalle_clinico:{...clean(clinical),diagnostico_principal_cie10:Number(clinical.diagnostico_principal_cie10)}};['tercero_contratante_id','medico_receptor_id','medio_transporte_id'].forEach(k=>{if(payload[k])payload[k]=Number(payload[k])});if(payload.fecha_traslado_programada)payload.fecha_traslado_programada=`${payload.fecha_traslado_programada.replace('T',' ')}:00`;const r=await crearReferencia(payload);router.push(`/referencias/${r?.data?.id||r?.id}`)}catch(e){error.value=obtenerMensajeError(e)}finally{saving.value=false}}onMounted(async()=>{const rs=await Promise.allSettled([consultarCatalogosReferencia(),listarEstablecimientos({activo:true}),listarPagadores(),listarMedicosReceptores(),listarDiagnosticos()]);if(rs[0].status==='fulfilled'){const s=rs[0].value?.data||rs[0].value;catalogs.prioridades=pick(s,['prioridades_referencia','prioridades']);catalogs.tipos=pick(s,['tipos_referencia','tipos']);catalogs.transportes=pick(s,['medios_transporte','transportes'])}if(rs[1].status==='fulfilled')establishments.value=array(rs[1].value);if(rs[2].status==='fulfilled')payers.value=array(rs[2].value);if(rs[3].status==='fulfilled')doctors.value=array(rs[3].value);if(rs[4].status==='fulfilled')diagnoses.value=array(rs[4].value)})
</script>
